class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        if monthly_limit_mib < 0:
            raise ValueError("Monthly limit cannot be negative.")
        self._limit_bytes: float = monthly_limit_mib * 1024 * 1024
        # Tracks accumulated upload bytes per month that count towards the quota
        self._used_bytes: dict[str, int] = {}
        # Tracks active/uploaded files per month: month -> {name: size_bytes}
        self._files: dict[str, dict[str, int]] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """Upload a file under a given month quota.

        month is a string like "2026-01".
        """
        if size_bytes <= 0:
            raise ValueError("File size must be greater than 0.")

        current_used = self._used_bytes.get(month, 0)
        if current_used + size_bytes > self._limit_bytes:
            raise ValueError("Upload exceeds the monthly quota limit.")

        self._used_bytes[month] = current_used + size_bytes
        if month not in self._files:
            self._files[month] = {}
        self._files[month][name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        """Delete a file.

        Deleting a file does not recover quota for the month.
        """
        if month in self._files and name in self._files[month]:
            del self._files[month][name]

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return self._used_bytes.get(month, 0)
```

